INSERT INTO public.courses (id, title, description, category, difficulty, estimated_minutes, published, position) VALUES
('c0000000-0000-0000-0000-000000000001', 'Phishing & Email Scams', 'Spot fraudulent emails, spoofed sender domains, and fake invoices targeting South Africans.', 'Email Security', 'Beginner', 15, true, 1),
('c0000000-0000-0000-0000-000000000002', 'WhatsApp & SMS Scams', 'Defend against banking SMS lures, fake parcel notices, and Hi Mom WhatsApp impersonation scams.', 'Mobile Messaging', 'Beginner', 12, true, 2),
('c0000000-0000-0000-0000-000000000003', 'Online Shopping & Payment Scams', 'Avoid fake proof of payment tricks, fraudulent Facebook Marketplace sellers, and escrow scams.', 'E-Commerce', 'Beginner', 15, true, 3),
('c0000000-0000-0000-0000-000000000004', 'Password Security & Managers', 'Create unbreakable passphrases, use password vaults, and check credential breaches.', 'Access Control', 'Beginner', 10, true, 4),
('c0000000-0000-0000-0000-000000000005', 'Multi-Factor Authentication (MFA)', 'Why passwords fail, authenticator apps vs SMS OTPs, and defending against SIM swaps.', 'Access Control', 'Intermediate', 12, true, 5),
('c0000000-0000-0000-0000-000000000006', 'Social Engineering & Pretexting', 'Understand psychological manipulation, urgent phone calls from fake fraud departments, and CEO fraud.', 'Human Defense', 'Intermediate', 15, true, 6),
('c0000000-0000-0000-0000-000000000007', 'Safe Browsing & Malicious Links', 'Inspect URL domain names, detect lookalike websites (typosquatting), and prevent dangerous APK downloads.', 'Web Safety', 'Beginner', 10, true, 7),
('c0000000-0000-0000-0000-000000000008', 'Protecting Personal Information', 'Safeguard your South African ID number, banking cards, proof of residence, and identity theft countermeasures.', 'Privacy', 'Beginner', 12, true, 8),
('c0000000-0000-0000-0000-000000000009', 'Cybersecurity Basics for Small Businesses', 'Essential digital hygiene for South African SMEs: guest WiFi segregation, access control, and 3-2-1 backups.', 'Business Protection', 'Intermediate', 20, true, 9),
('c0000000-0000-0000-0000-000000000010', 'Introduction to POPIA & Personal Data', 'The Protection of Personal Information Act (POPIA): lawful conditions, customer consent, and breach notification duties.', 'Compliance & Law', 'Intermediate', 18, true, 10)
INSERT INTO public.checklist_items (id, title, description, category, recommended_action, position) VALUES
('b0000000-0000-0000-0000-000000000001', 'Unique Passwords for Business Accounts', 'Ensure business email, banking, accounting software, and admin panels use distinct, non-reused passphrases.', 'Account Security', 'Deploy a business password manager (e.g. Bitwarden or 1Password) so team members do not reuse personal passwords.', 1),
('b0000000-0000-0000-0000-000000000002', 'Multi-Factor Authentication (MFA) Enabled', 'Enforce MFA across all critical business accounts, prioritizing app-based authenticators over SMS.', 'Account Security', 'Turn on MFA in Google Workspace, Microsoft 365, Xero, and banking portals.', 2),
('b0000000-0000-0000-0000-000000000003', 'Former Employees Access Revocation', 'Revoke email, cloud drives, VPN, and internal system access immediately whenever an employee leaves.', 'Account Security', 'Maintain a formal offboarding checklist signed by the direct manager on the employees departure day.', 3),
('b0000000-0000-0000-0000-000000000004', 'Restricted Administrative Access', 'Staff use standard non-admin accounts for daily work; administrator privileges are strictly reserved for IT maintenance.', 'Account Security', 'Audit user permissions monthly to prevent privilege creep and remove unnecessary admin roles.', 4),
('b0000000-0000-0000-0000-000000000005', 'Operating Systems and Software Patched', 'Enable automatic updates for Windows, macOS, Android, iOS, and critical business applications.', 'Devices and Software', 'Schedule weekly maintenance windows or turn on automatic patching for OS and browser updates.', 5),
('b0000000-0000-0000-0000-000000000006', 'Device Screen Locks & Auto-Lock Timers', 'All business laptops, tablets, and phones enforce PINs, biometric locks, or passcodes with a 3-5 minute auto-lock timeout.', 'Devices and Software', 'Configure group policy or device management to mandate screen locks on all company-used devices.', 6),
('b0000000-0000-0000-0000-000000000007', 'Endpoint Security Software Maintained', 'Workstations have reputable endpoint protection (antivirus/EDR) active with real-time definitions updating daily.', 'Devices and Software', 'Check that Microsoft Defender or equivalent endpoint software is running and scans weekly.', 7),
('b0000000-0000-0000-0000-000000000008', 'Unnecessary & Shadow IT Applications Removed', 'Prevent installation of unauthorized third-party software, peer-to-peer apps, or unvetted browser extensions.', 'Devices and Software', 'Conduct a software inventory and uninstall legacy, unpatched, or unnecessary programs.', 8),
('b0000000-0000-0000-0000-000000000009', '3-2-1 Backup Strategy Implemented', 'Maintain 3 copies of critical business data, on 2 different media formats, with 1 copy stored securely offsite or in cloud backup.', 'Data Protection', 'Set up automated daily cloud backups for financial databases and key customer records.', 9),
('b0000000-0000-0000-0000-000000000010', 'Periodic Backup Recovery Testing', 'Test restoring data from backups at least once every quarter to ensure backup files are not corrupt.', 'Data Protection', 'Run a test restoration of a sample database or folder to confirm your team can recover within hours.', 10),
('b0000000-0000-0000-0000-000000000011', 'Sensitive Files Access Tiers & POPIA Compliance', 'Confidential customer details and payroll records are encrypted and accessible only to designated personnel.', 'Data Protection', 'Classify data into Public, Internal, and Confidential. Enforce strict folder permissions.', 11),
('b0000000-0000-0000-0000-000000000012', 'Employee Phishing & Scam Training', 'Conduct regular awareness sessions on South African cyber threats (SARS refund scams, WhatsApp impersonation, invoice fraud).', 'Employee Awareness', 'Use CyberShield Academy courses during employee onboarding and run quarterly refresher discussions.', 12),
('b0000000-0000-0000-0000-000000000013', 'Clear Reporting Workflow for Suspicious Activity', 'Staff know exactly how and to whom to report suspicious emails, unexpected bank detail changes, or phone calls.', 'Employee Awareness', 'Set up a dedicated internal mailbox (e.g. security@yourcompany.co.za) and celebrate employees who report threats.', 13),
('b0000000-0000-0000-0000-000000000014', 'Documented Incident Response Contact Roster', 'Emergency contacts for your IT provider, bank fraud hotline, insurer, and legal counsel are documented offline.', 'Incident Readiness', 'Print a physical laminated card with IT support, bank fraud numbers, and leadership contact details.', 14),
('b0000000-0000-0000-0000-000000000015', 'Data Breach Notification Procedure (Information Regulator)', 'The business has a documented process for reporting security compromises to the Information Regulator under POPIA Section 22.', 'Incident Readiness', 'Bookmark the Information Regulator breach portal (inforegulator.org.za) and draft an emergency notification template.', 15)
